def for_var(var_id, direction, level):
    """Return guidance for a variable that is off in `direction` ('hi'/'lo') at `level` (1 warn, 2 alert)."""
    d = C.get(var_id, {})
    g = d.get(direction) or d.get("hi" if direction == "lo" else "lo")
    if not g:
        return None
    steps = list(g["do"]) + (list(g.get("alert", [])) if level >= 2 else [])
    return {"steps": steps, "sup": g.get("sup", []), "ref": g.get("ref", [])}
